<?php
namespace App\Policies;use App\Models\{CertificateTemplate,User};final class CertificateTemplatePolicy{private function allowed(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','CERTIFICATE_MANAGER'])->exists();}public function viewAny(User$u):bool{return$this->allowed($u);}public function view(User$u,CertificateTemplate$m):bool{return$this->allowed($u);}public function create(User$u):bool{return$this->allowed($u);}public function update(User$u,CertificateTemplate$m):bool{return$this->allowed($u)&&$m->status==='DRAFT';}public function delete(User$u,CertificateTemplate$m):bool{return false;}}
